/* LingWay: complete NEW installation for SQL Server / SSMS.
   Creates database, tables, indexes, roles, views and educational content.
   NO user accounts, passwords, personal results or migration archives.
   Open this file in SSMS and execute the entire file in normal query mode.
   Existing database LingWay is deliberately NOT modified.
   Run the entire file. Existing installations require separate upgrade migrations.
*/
USE [master];
GO
IF DB_ID(N'LingWay') IS NOT NULL
BEGIN
    PRINT N'LingWay already exists. Installation skipped; existing data is unchanged.';
END
ELSE
BEGIN
-- SECTION: 001_Initial.sql
EXEC [master].sys.sp_executesql N'/* LingWay — SQL Server database for ASP.NET Core / EF Core.
   Execute in SSMS with Windows authentication on localhost.
   Identity model: IdentityUser<Guid>, IdentityRole<Guid>.
   Non-destructive bootstrap: no DROP, no passwords or application secrets.
   Existing prototype data is NOT imported by this script.
*/
USE [master];
';
EXEC [master].sys.sp_executesql N'
IF DB_ID(N''LingWay'') IS NULL
    EXEC(N''CREATE DATABASE [LingWay]'');
';
EXEC [LingWay].sys.sp_executesql N'
USE [LingWay];
';
EXEC [LingWay].sys.sp_executesql N'
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
';
EXEC [LingWay].sys.sp_executesql N'
IF OBJECT_ID(N''dbo.SchemaVersions'', N''U'') IS NULL
BEGIN
    IF EXISTS (SELECT 1 FROM sys.tables WHERE is_ms_shipped=0)
        THROW 50001, N''LingWay already contains unrelated tables. No changes applied.'', 1;
    BEGIN TRY
    BEGIN TRANSACTION;

    CREATE TABLE dbo.SchemaVersions (
        Version int NOT NULL CONSTRAINT PK_SchemaVersions PRIMARY KEY,
        AppliedAt datetime2 NOT NULL CONSTRAINT DF_SchemaVersions_Date DEFAULT SYSUTCDATETIME(),
        Description nvarchar(300) NOT NULL
    );

    -- ASP.NET Core Identity: GUID primary keys, standard fields and indexes.
    CREATE TABLE dbo.AspNetRoles (
        Id uniqueidentifier NOT NULL CONSTRAINT PK_AspNetRoles PRIMARY KEY,
        Name nvarchar(256) NULL,
        NormalizedName nvarchar(256) NULL,
        ConcurrencyStamp nvarchar(max) NULL
    );
    CREATE UNIQUE INDEX RoleNameIndex ON dbo.AspNetRoles(NormalizedName) WHERE NormalizedName IS NOT NULL;
    CREATE TABLE dbo.AspNetUsers (
        Id uniqueidentifier NOT NULL CONSTRAINT PK_AspNetUsers PRIMARY KEY,
        UserName nvarchar(256) NULL,
        NormalizedUserName nvarchar(256) NULL,
        Email nvarchar(256) NULL,
        NormalizedEmail nvarchar(256) NULL,
        EmailConfirmed bit NOT NULL CONSTRAINT DF_Users_EmailConfirmed DEFAULT 0,
        PasswordHash nvarchar(max) NULL,
        SecurityStamp nvarchar(max) NULL,
        ConcurrencyStamp nvarchar(max) NULL,
        PhoneNumber nvarchar(max) NULL,
        PhoneNumberConfirmed bit NOT NULL CONSTRAINT DF_Users_PhoneConfirmed DEFAULT 0,
        TwoFactorEnabled bit NOT NULL CONSTRAINT DF_Users_TwoFactor DEFAULT 0,
        LockoutEnd datetimeoffset NULL,
        LockoutEnabled bit NOT NULL CONSTRAINT DF_Users_Lockout DEFAULT 1,
        AccessFailedCount int NOT NULL CONSTRAINT DF_Users_Failed DEFAULT 0
    );
    CREATE UNIQUE INDEX UserNameIndex ON dbo.AspNetUsers(NormalizedUserName) WHERE NormalizedUserName IS NOT NULL;
    CREATE INDEX EmailIndex ON dbo.AspNetUsers(NormalizedEmail);
    CREATE TABLE dbo.AspNetUserRoles (
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        RoleId uniqueidentifier NOT NULL REFERENCES dbo.AspNetRoles(Id) ON DELETE CASCADE,
        CONSTRAINT PK_AspNetUserRoles PRIMARY KEY(UserId,RoleId)
    );
    CREATE INDEX IX_AspNetUserRoles_RoleId ON dbo.AspNetUserRoles(RoleId);
    CREATE TABLE dbo.AspNetUserClaims (
        Id int IDENTITY NOT NULL CONSTRAINT PK_AspNetUserClaims PRIMARY KEY,
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        ClaimType nvarchar(max) NULL, ClaimValue nvarchar(max) NULL
    );
    CREATE INDEX IX_AspNetUserClaims_UserId ON dbo.AspNetUserClaims(UserId);
    CREATE TABLE dbo.AspNetRoleClaims (
        Id int IDENTITY NOT NULL CONSTRAINT PK_AspNetRoleClaims PRIMARY KEY,
        RoleId uniqueidentifier NOT NULL REFERENCES dbo.AspNetRoles(Id) ON DELETE CASCADE,
        ClaimType nvarchar(max) NULL, ClaimValue nvarchar(max) NULL
    );
    CREATE INDEX IX_AspNetRoleClaims_RoleId ON dbo.AspNetRoleClaims(RoleId);
    CREATE TABLE dbo.AspNetUserLogins (
        LoginProvider nvarchar(128) NOT NULL, ProviderKey nvarchar(128) NOT NULL,
        ProviderDisplayName nvarchar(max) NULL,
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        CONSTRAINT PK_AspNetUserLogins PRIMARY KEY(LoginProvider,ProviderKey)
    );
    CREATE INDEX IX_AspNetUserLogins_UserId ON dbo.AspNetUserLogins(UserId);
    CREATE TABLE dbo.AspNetUserTokens (
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        LoginProvider nvarchar(128) NOT NULL, Name nvarchar(128) NOT NULL, Value nvarchar(max) NULL,
        CONSTRAINT PK_AspNetUserTokens PRIMARY KEY(UserId,LoginProvider,Name)
    );

    CREATE TABLE dbo.UserProfiles (
        UserId uniqueidentifier NOT NULL CONSTRAINT PK_UserProfiles PRIMARY KEY REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        FirstName nvarchar(40) NOT NULL, LastName nvarchar(60) NOT NULL,
        AvatarPath nvarchar(500) NULL, About nvarchar(1000) NULL,
        EnglishLevel varchar(2) NULL CONSTRAINT CK_Profile_Level CHECK(EnglishLevel IN (''A1'',''A2'',''B1'',''B2'',''C1'',''C2'')),
        LearningGoal nvarchar(300) NULL, Destination nvarchar(200) NULL, TripDate date NULL,
        DailyMinutes int NOT NULL DEFAULT 15 CONSTRAINT CK_Profile_Minutes CHECK(DailyMinutes BETWEEN 1 AND 240),
        Theme varchar(10) NOT NULL DEFAULT ''system'' CONSTRAINT CK_Profile_Theme CHECK(Theme IN (''light'',''dark'',''system'')),
        Language varchar(5) NOT NULL DEFAULT ''ru'',
        SpeechRate decimal(3,2) NOT NULL DEFAULT 1 CONSTRAINT CK_Profile_Rate CHECK(SpeechRate BETWEEN 0.50 AND 2.00),
        OnboardingCompleted bit NOT NULL DEFAULT 0,
        NotificationsEnabled bit NOT NULL DEFAULT 0,
        ReminderTime time(0) NOT NULL DEFAULT ''19:00'',
        QuietStart time(0) NOT NULL DEFAULT ''22:00'', QuietEnd time(0) NOT NULL DEFAULT ''08:00'',
        TimeZoneId nvarchar(100) NOT NULL DEFAULT ''Russian Standard Time'',
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        RowVersion rowversion NOT NULL
    );
    CREATE TABLE dbo.Modules (
        Id int IDENTITY NOT NULL CONSTRAINT PK_Modules PRIMARY KEY,
        Title nvarchar(200) NOT NULL, Description nvarchar(2000) NOT NULL,
        SortOrder int NOT NULL CONSTRAINT UQ_Modules_Order UNIQUE,
        IsEmergency bit NOT NULL DEFAULT 0, IsPublished bit NOT NULL DEFAULT 0
    );
    CREATE TABLE dbo.Lessons (
        Id int IDENTITY NOT NULL CONSTRAINT PK_Lessons PRIMARY KEY,
        ModuleId int NOT NULL REFERENCES dbo.Modules(Id),
        Title nvarchar(200) NOT NULL, Description nvarchar(2000) NOT NULL,
        EnglishLevel varchar(2) NOT NULL DEFAULT ''A1'' CONSTRAINT CK_Lessons_Level CHECK(EnglishLevel IN (''A1'',''A2'',''B1'',''B2'',''C1'',''C2'')),
        SortOrder int NOT NULL, IsPublished bit NOT NULL DEFAULT 0,
        RowVersion rowversion NOT NULL,
        CONSTRAINT UQ_Lessons_Order UNIQUE(ModuleId,SortOrder)
    );
    -- Immutable version snapshots include steps, routes, vocabulary and criteria.
    CREATE TABLE dbo.LessonVersions (
        LessonId int NOT NULL REFERENCES dbo.Lessons(Id),
        Version int NOT NULL CONSTRAINT CK_LessonVersions_Positive CHECK(Version>0),
        StepsJson nvarchar(max) NOT NULL CONSTRAINT CK_LessonVersions_Steps CHECK(ISJSON(StepsJson)=1),
        MetadataJson nvarchar(max) NOT NULL CONSTRAINT CK_LessonVersions_Meta CHECK(ISJSON(MetadataJson)=1),
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT PK_LessonVersions PRIMARY KEY(LessonId,Version)
    );
    CREATE TABLE dbo.StudyGroups (
        Id int IDENTITY NOT NULL CONSTRAINT PK_StudyGroups PRIMARY KEY,
        Name nvarchar(200) NOT NULL,
        JoinCode varchar(32) NOT NULL CONSTRAINT UQ_StudyGroups_Code UNIQUE,
        TeacherId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id),
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
    );
    CREATE INDEX IX_StudyGroups_TeacherId ON dbo.StudyGroups(TeacherId);
    CREATE TABLE dbo.GroupMembers (
        GroupId int NOT NULL REFERENCES dbo.StudyGroups(Id) ON DELETE CASCADE,
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id),
        JoinedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT PK_GroupMembers PRIMARY KEY(GroupId,UserId)
    );
    CREATE INDEX IX_GroupMembers_UserId ON dbo.GroupMembers(UserId);
    CREATE TABLE dbo.Assignments (
        Id int IDENTITY NOT NULL CONSTRAINT PK_Assignments PRIMARY KEY,
        GroupId int NOT NULL REFERENCES dbo.StudyGroups(Id) ON DELETE CASCADE,
        ModuleId int NOT NULL REFERENCES dbo.Modules(Id),
        DueDate date NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT UQ_Assignments_GroupModule UNIQUE(GroupId,ModuleId)
    );
    CREATE TABLE dbo.Attempts (
        Id uniqueidentifier NOT NULL CONSTRAINT PK_Attempts PRIMARY KEY,
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id),
        LessonId int NOT NULL, LessonVersion int NOT NULL,
        Score decimal(5,2) NOT NULL CONSTRAINT CK_Attempts_Score CHECK(Score BETWEEN 0 AND 100),
        Stars tinyint NOT NULL CONSTRAINT CK_Attempts_Stars CHECK(Stars BETWEEN 0 AND 3),
        IsPassed bit NOT NULL,
        DurationSeconds int NOT NULL CONSTRAINT CK_Attempts_Duration CHECK(DurationSeconds>=0),
        CompletedAt datetime2 NOT NULL, ReceivedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT FK_Attempts_Version FOREIGN KEY(LessonId,LessonVersion) REFERENCES dbo.LessonVersions(LessonId,Version)
    );
    CREATE INDEX IX_Attempts_UserDate ON dbo.Attempts(UserId,CompletedAt);
    CREATE INDEX IX_Attempts_LessonDate ON dbo.Attempts(LessonId,CompletedAt);
    CREATE TABLE dbo.AttemptAnswers (
        AttemptId uniqueidentifier NOT NULL REFERENCES dbo.Attempts(Id) ON DELETE CASCADE,
        SequenceNumber int NOT NULL, StepIndex int NOT NULL,
        Prompt nvarchar(2000) NOT NULL, ExpectedAnswer nvarchar(2000) NOT NULL, UserAnswer nvarchar(2000) NOT NULL,
        Status varchar(15) NOT NULL CONSTRAINT CK_Answers_Status CHECK(Status IN (''correct'',''near'',''incorrect'',''unrecognized'',''studied'')),
        HintLevel tinyint NOT NULL DEFAULT 0 CONSTRAINT CK_Answers_Hint CHECK(HintLevel BETWEEN 0 AND 3),
        CONSTRAINT PK_AttemptAnswers PRIMARY KEY(AttemptId,SequenceNumber)
    );
    CREATE TABLE dbo.Phrases (
        Id int IDENTITY NOT NULL CONSTRAINT PK_Phrases PRIMARY KEY,
        English nvarchar(400) NOT NULL CONSTRAINT UQ_Phrases_English UNIQUE,
        Translation nvarchar(500) NOT NULL, Transcription nvarchar(500) NULL,
        Category nvarchar(100) NOT NULL, AudioPath nvarchar(500) NULL
    );
    CREATE TABLE dbo.FavoritePhrases (
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        PhraseId int NOT NULL REFERENCES dbo.Phrases(Id),
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT PK_FavoritePhrases PRIMARY KEY(UserId,PhraseId)
    );
    CREATE TABLE dbo.RecentPhrases (
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        PhraseId int NOT NULL REFERENCES dbo.Phrases(Id), LastViewedAt datetime2 NOT NULL,
        CONSTRAINT PK_RecentPhrases PRIMARY KEY(UserId,PhraseId)
    );
    CREATE TABLE dbo.VocabularyItems (
        Id int IDENTITY NOT NULL CONSTRAINT PK_VocabularyItems PRIMARY KEY,
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        English nvarchar(400) NOT NULL, Translation nvarchar(500) NOT NULL, Transcription nvarchar(500) NULL,
        SourcePhraseId int NULL REFERENCES dbo.Phrases(Id),
        DueAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        ReviewStreak int NOT NULL DEFAULT 0 CONSTRAINT CK_Vocabulary_Streak CHECK(ReviewStreak>=0),
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT UQ_Vocabulary_UserWord UNIQUE(UserId,English)
    );
    CREATE INDEX IX_Vocabulary_UserDue ON dbo.VocabularyItems(UserId,DueAt);
    CREATE TABLE dbo.Achievements (
        Code varchar(50) NOT NULL CONSTRAINT PK_Achievements PRIMARY KEY,
        Title nvarchar(100) NOT NULL, Description nvarchar(500) NOT NULL
    );
    CREATE TABLE dbo.UserAchievements (
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        AchievementCode varchar(50) NOT NULL REFERENCES dbo.Achievements(Code),
        EarnedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT PK_UserAchievements PRIMARY KEY(UserId,AchievementCode)
    );
    CREATE TABLE dbo.PassportStamps (
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        ModuleId int NOT NULL REFERENCES dbo.Modules(Id), EarnedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
        CONSTRAINT PK_PassportStamps PRIMARY KEY(UserId,ModuleId)
    );
    CREATE TABLE dbo.ContentPackages (
        Id int IDENTITY NOT NULL CONSTRAINT PK_ContentPackages PRIMARY KEY,
        ContentJson nvarchar(max) NOT NULL CONSTRAINT CK_Packages_Content CHECK(ISJSON(ContentJson)=1),
        SizeBytes bigint NOT NULL CONSTRAINT CK_Packages_Size CHECK(SizeBytes>=0),
        Sha256 char(64) NOT NULL, PublishedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
    );
    CREATE TABLE dbo.Notifications (
        Id bigint IDENTITY NOT NULL CONSTRAINT PK_Notifications PRIMARY KEY,
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        Title nvarchar(200) NOT NULL, Body nvarchar(2000) NOT NULL, TargetUrl nvarchar(500) NULL,
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), ReadAt datetime2 NULL
    );
    CREATE INDEX IX_Notifications_UserDate ON dbo.Notifications(UserId,CreatedAt);
    CREATE TABLE dbo.PushSubscriptions (
        Id bigint IDENTITY NOT NULL CONSTRAINT PK_PushSubscriptions PRIMARY KEY,
        UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
        Endpoint nvarchar(2000) NOT NULL,
        EndpointHash binary(32) NOT NULL CONSTRAINT UQ_Push_EndpointHash UNIQUE,
        P256dh varchar(200) NOT NULL, Auth varchar(200) NOT NULL,
        LastSentAt datetime2 NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
    );
    CREATE INDEX IX_Push_User ON dbo.PushSubscriptions(UserId);
    CREATE TABLE dbo.MediaFiles (
        Id uniqueidentifier NOT NULL CONSTRAINT PK_MediaFiles PRIMARY KEY,
        UploadedBy uniqueidentifier NULL REFERENCES dbo.AspNetUsers(Id),
        StoragePath nvarchar(500) NOT NULL, OriginalName nvarchar(255) NOT NULL,
        ContentType varchar(100) NOT NULL, SizeBytes bigint NOT NULL CHECK(SizeBytes>=0),
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
    );
    CREATE TABLE dbo.ImportBatches (
        Id uniqueidentifier NOT NULL CONSTRAINT PK_ImportBatches PRIMARY KEY,
        UserId uniqueidentifier NULL REFERENCES dbo.AspNetUsers(Id),
        Kind varchar(20) NOT NULL CHECK(Kind IN (''students'',''phrases'')),
        AddedCount int NOT NULL CHECK(AddedCount>=0), ErrorCount int NOT NULL CHECK(ErrorCount>=0),
        ErrorsJson nvarchar(max) NOT NULL CHECK(ISJSON(ErrorsJson)=1),
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
    );
    CREATE TABLE dbo.AuditEvents (
        Id bigint IDENTITY NOT NULL CONSTRAINT PK_AuditEvents PRIMARY KEY,
        UserId uniqueidentifier NULL REFERENCES dbo.AspNetUsers(Id),
        Action nvarchar(300) NOT NULL,
        CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
    );
    CREATE INDEX IX_AuditEvents_Date ON dbo.AuditEvents(CreatedAt);

    INSERT dbo.AspNetRoles(Id,Name,NormalizedName,ConcurrencyStamp) VALUES
      (''11111111-1111-4111-8111-111111111111'',N''Student'',N''STUDENT'',CONVERT(nvarchar(36),NEWID())),
      (''22222222-2222-4222-8222-222222222222'',N''Teacher'',N''TEACHER'',CONVERT(nvarchar(36),NEWID())),
      (''33333333-3333-4333-8333-333333333333'',N''Admin'',N''ADMIN'',CONVERT(nvarchar(36),NEWID()));
    INSERT dbo.Modules(Title,Description,SortOrder,IsEmergency,IsPublished) VALUES
      (N''Аэропорт'',N''Регистрация, багаж и паспортный контроль'',1,0,0),
      (N''Самолёт'',N''Место, обслуживание и пересадка'',2,0,0),
      (N''Отель'',N''Заселение, просьбы и выезд'',3,0,0),
      (N''Кафе'',N''Заказ, аллергии и оплата'',4,0,0),
      (N''Город и транспорт'',N''Маршруты, билеты и такси'',5,0,0),
      (N''Магазин'',N''Выбор товара, оплата и возврат'',6,0,0),
      (N''Экстренные ситуации'',N''Помощь, здоровье и документы'',7,1,0);
    INSERT dbo.Achievements(Code,Title,Description) VALUES
      (''first-lesson'',N''Первый шаг'',N''Завершите первый урок''),
      (''perfect'',N''Без ошибок'',N''Получите 100% за урок''),
      (''ten-lessons'',N''В пути'',N''Завершите 10 тренировок'');
    INSERT dbo.SchemaVersions(Version,Description) VALUES(1,N''Initial LingWay schema; Identity GUID keys'');
    COMMIT TRANSACTION;
    PRINT N''LingWay database schema created successfully.'';
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END
ELSE
BEGIN
    IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=1)
        THROW 50002, N''Unknown database schema version. No changes applied.'',1;
    PRINT N''LingWay schema already exists; no data changed.'';
END;
';
EXEC [LingWay].sys.sp_executesql N'
SELECT DB_NAME() AS DatabaseName,COUNT(*) AS TableCount FROM sys.tables WHERE is_ms_shipped=0;
';
-- SECTION: 002_Compatibility.sql
EXEC [LingWay].sys.sp_executesql N'-- Compatibility schema only. No historical accounts, hashes or migration data.
SET XACT_ABORT ON;
SET QUOTED_IDENTIFIER ON;
BEGIN TRANSACTION;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=2)
BEGIN
IF SCHEMA_ID(N''migration'') IS NULL EXEC(N''CREATE SCHEMA migration'');
CREATE TABLE migration.SourceRows (
 SourceTable nvarchar(60) NOT NULL, RowNumber int NOT NULL,
 RowJson nvarchar(max) NOT NULL CHECK(ISJSON(RowJson)=1),
 CONSTRAINT PK_MigrationSource PRIMARY KEY(SourceTable,RowNumber));
CREATE TABLE migration.EntityMap (
 EntityType nvarchar(60) NOT NULL, SourceId nvarchar(100) NOT NULL, TargetId nvarchar(100) NOT NULL,
 CONSTRAINT PK_MigrationMap PRIMARY KEY(EntityType,SourceId));
CREATE TABLE dbo.LegacyPasswordCredentials (
 UserId uniqueidentifier NOT NULL PRIMARY KEY REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
 Algorithm varchar(30) NOT NULL, SaltHex varchar(32) NOT NULL, HashHex varchar(128) NOT NULL,
 WorkFactor int NOT NULL, BlockSize int NOT NULL, Parallelism int NOT NULL,
 MigratedToIdentityAt datetime2 NULL);
CREATE TABLE dbo.PhraseReviews (
 UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
 PhraseId int NOT NULL REFERENCES dbo.Phrases(Id),
 ReviewStreak int NOT NULL CHECK(ReviewStreak>=0), DueAt datetime2 NOT NULL,
 CONSTRAINT PK_PhraseReviews PRIMARY KEY(UserId,PhraseId));
ALTER TABLE dbo.AspNetUsers ADD LegacyId int NULL, LegacyDisplayName nvarchar(200) NULL;
EXEC(N''CREATE UNIQUE INDEX IX_Users_LegacyId ON dbo.AspNetUsers(LegacyId) WHERE LegacyId IS NOT NULL'');
ALTER TABLE dbo.UserProfiles ADD LegacyProfileJson nvarchar(max) NULL, AvatarDataUri nvarchar(max) NULL, IsGuest bit NOT NULL DEFAULT 0;
EXEC(N''ALTER TABLE dbo.UserProfiles ADD CONSTRAINT CK_Profile_LegacyJson CHECK(LegacyProfileJson IS NULL OR ISJSON(LegacyProfileJson)=1)'');
ALTER TABLE dbo.Attempts ADD LegacyAnswersJson nvarchar(max) NULL;
EXEC(N''ALTER TABLE dbo.Attempts ADD CONSTRAINT CK_Attempts_LegacyJson CHECK(LegacyAnswersJson IS NULL OR ISJSON(LegacyAnswersJson)=1)'');
ALTER TABLE dbo.AttemptAnswers ADD ExerciseType varchar(30) NULL, Tries int NULL, LegacyAnswerJson nvarchar(max) NULL;
ALTER TABLE dbo.ContentPackages ADD LegacyPayloadJson nvarchar(max) NULL;
ALTER TABLE dbo.AuditEvents ADD LegacyId int NULL;
INSERT dbo.SchemaVersions(Version,Description) VALUES(2,N''Compatibility schema without personal data'');
END;
COMMIT;
';
-- SECTION: 003_Application.sql
EXEC [LingWay].sys.sp_executesql N'-- Additive application schema. Existing imported data is preserved.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID(N''dbo.ApplicationCodes'',N''U'') IS NULL
CREATE TABLE dbo.ApplicationCodes (
 UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
 Purpose varchar(10) NOT NULL,
 CodeHash char(64) NOT NULL,
 ExpiresAt datetime2 NOT NULL,
 Tries int NOT NULL DEFAULT 0,
 PRIMARY KEY(UserId,Purpose)
);
IF OBJECT_ID(N''dbo.UserPublicId'',N''SO'') IS NULL
BEGIN
 DECLARE @next bigint=(SELECT ISNULL(MAX(LegacyId),0)+1 FROM dbo.AspNetUsers);
 EXEC(N''CREATE SEQUENCE dbo.UserPublicId AS int START WITH ''+@next+N'' INCREMENT BY 1'');
END;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=3)
 INSERT dbo.SchemaVersions(Version,Description) VALUES(3,N''ASP.NET Core: one-time email codes and stable public user identifiers'');
COMMIT;
';
-- SECTION: 004_Hardening.sql
EXEC [LingWay].sys.sp_executesql N'SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF COL_LENGTH(''dbo.Attempts'',''RequestHash'') IS NULL
    ALTER TABLE dbo.Attempts ADD RequestHash char(64) NULL;
IF OBJECT_ID(''dbo.AccountDeletions'',''U'') IS NULL
    CREATE TABLE dbo.AccountDeletions(UserId uniqueidentifier NOT NULL PRIMARY KEY, LegacyId int NULL, DeletedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=4)
    INSERT dbo.SchemaVersions(Version,Description) VALUES(4,N''Idempotent submission hashes and deletion ledger'');
COMMIT;
';
-- SECTION: 005_Notifications.sql
EXEC [LingWay].sys.sp_executesql N'SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID(''dbo.SiteNotifications'',''U'') IS NULL
BEGIN
 CREATE TABLE dbo.SiteNotifications(
  Id uniqueidentifier NOT NULL PRIMARY KEY,
  UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
  EventKey nvarchar(150) NOT NULL,
  Title nvarchar(200) NOT NULL,
  Body nvarchar(1000) NOT NULL,
  Href nvarchar(200) NOT NULL,
  CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),
  ReadAt datetime2 NULL,
  CONSTRAINT UQ_SiteNotifications_Event UNIQUE(UserId,EventKey)
 );
 CREATE INDEX IX_SiteNotifications_User ON dbo.SiteNotifications(UserId,CreatedAt DESC);
END;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=5)
 INSERT dbo.SchemaVersions(Version,Description) VALUES(5,N''Persistent in-site notification inbox'');
COMMIT;
';
-- SECTION: 006_LessonProgress.sql
EXEC [LingWay].sys.sp_executesql N'SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID(''dbo.LessonProgress'',''U'') IS NULL
 CREATE TABLE dbo.LessonProgress(
 UserId uniqueidentifier NOT NULL REFERENCES dbo.AspNetUsers(Id) ON DELETE CASCADE,
 LessonId int NOT NULL REFERENCES dbo.Lessons(Id),
 AttemptId uniqueidentifier NOT NULL,
 StateJson nvarchar(max) NOT NULL CHECK(ISJSON(StateJson)=1),
 UpdatedAt bigint NOT NULL,
 CONSTRAINT PK_LessonProgress PRIMARY KEY(UserId,LessonId));
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=6)
 INSERT dbo.SchemaVersions(Version,Description) VALUES(6,N''Account lesson checkpoints'');
COMMIT;
';
-- SECTION: 007_PrivacyMinimization.sql
EXEC [LingWay].sys.sp_executesql N'SET XACT_ABORT ON;
BEGIN TRANSACTION;
-- Operational users/results remain intact; raw import copies are not needed at runtime.
DELETE migration.SourceRows WHERE SourceTable NOT IN
 (''modules'',''lessons'',''lesson_versions'',''phrases'',''packages'',''migrations'');
DELETE migration.EntityMap WHERE EntityType IN (''users'',''attempts'',''groups'',''members'');
DELETE credentials FROM dbo.LegacyPasswordCredentials credentials
 JOIN dbo.AspNetUsers users ON users.Id=credentials.UserId
 WHERE users.PasswordHash IS NOT NULL;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=7)
 INSERT dbo.SchemaVersions(Version,Description) VALUES(7,N''Remove redundant personal import archives and migrated credentials'');
COMMIT;
';
-- SECTION: 008_IndividualAssignments.sql
EXEC [LingWay].sys.sp_executesql N'SET XACT_ABORT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
BEGIN TRANSACTION;
IF COL_LENGTH(''dbo.Assignments'',''StudentId'') IS NULL
BEGIN
 ALTER TABLE dbo.Assignments ADD StudentId uniqueidentifier NULL;
 ALTER TABLE dbo.Assignments ADD CONSTRAINT FK_Assignments_Student FOREIGN KEY(StudentId) REFERENCES dbo.AspNetUsers(Id);
 ALTER TABLE dbo.Assignments DROP CONSTRAINT UQ_Assignments_GroupModule;
END;
COMMIT;
';
EXEC [LingWay].sys.sp_executesql N'
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=''UX_Assignments_Group'' AND object_id=OBJECT_ID(''dbo.Assignments''))
 CREATE UNIQUE INDEX UX_Assignments_Group ON dbo.Assignments(GroupId,ModuleId) WHERE StudentId IS NULL;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name=''UX_Assignments_Student'' AND object_id=OBJECT_ID(''dbo.Assignments''))
 CREATE UNIQUE INDEX UX_Assignments_Student ON dbo.Assignments(GroupId,ModuleId,StudentId) WHERE StudentId IS NOT NULL;
IF NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE Version=8)
 INSERT dbo.SchemaVersions(Version,Description) VALUES(8,N''Individual assignments within teacher group scope'');
';
-- SECTION: 009_Views.sql
EXEC [LingWay].sys.sp_executesql N'USE [LingWay];
';
EXEC [LingWay].sys.sp_executesql N'
CREATE OR ALTER VIEW dbo.vwUsers AS
SELECT u.LegacyId AS PrototypeUserId,u.Id,u.LegacyDisplayName AS DisplayName,
       p.FirstName,p.LastName,u.Email,r.Name AS Role,u.EmailConfirmed,
       p.EnglishLevel,p.DailyMinutes,p.Destination,p.TripDate,
       CONVERT(bit,CASE WHEN p.AvatarDataUri IS NOT NULL OR p.AvatarPath IS NOT NULL THEN 1 ELSE 0 END) AS HasAvatar
FROM dbo.AspNetUsers u
JOIN dbo.UserProfiles p ON p.UserId=u.Id
JOIN dbo.AspNetUserRoles ur ON ur.UserId=u.Id
JOIN dbo.AspNetRoles r ON r.Id=ur.RoleId;
';
EXEC [LingWay].sys.sp_executesql N'
CREATE OR ALTER VIEW dbo.vwLessons AS
SELECT l.Id,l.Title,m.Title AS Module,l.ModuleId,l.EnglishLevel,l.IsPublished,
       v.Version AS CurrentVersion,
       (SELECT COUNT(*) FROM OPENJSON(v.StepsJson)) AS TotalStepNodes,
       TRY_CONVERT(int,JSON_VALUE(v.MetadataJson,''$.dialogue_paths'')) AS DialoguePaths,
       TRY_CONVERT(int,JSON_VALUE(v.MetadataJson,''$.criteria.pass_score'')) AS PassScore
FROM dbo.Lessons l JOIN dbo.Modules m ON m.Id=l.ModuleId
CROSS APPLY(SELECT TOP(1) x.Version,x.StepsJson,x.MetadataJson FROM dbo.LessonVersions x WHERE x.LessonId=l.Id ORDER BY x.Version DESC) v;
';
EXEC [LingWay].sys.sp_executesql N'
CREATE OR ALTER VIEW dbo.vwLessonSteps AS
SELECT l.Id AS LessonId,l.Title,v.Version,CONVERT(int,s.[key]) AS StepIndex,
       JSON_VALUE(s.value,''$.type'') AS ExerciseType,
       JSON_VALUE(s.value,''$.prompt'') AS Prompt,
       JSON_VALUE(s.value,''$.translation'') AS Translation,
       JSON_QUERY(s.value,''$.accepted'') AS AcceptedAnswersJson,
       JSON_QUERY(s.value,''$.options'') AS OptionsJson,
       JSON_QUERY(s.value,''$.hints'') AS HintsJson,
       JSON_QUERY(s.value,''$.routes'') AS RoutesJson,
       TRY_CONVERT(int,JSON_VALUE(s.value,''$.next'')) AS NextStepIndex
FROM dbo.Lessons l
CROSS APPLY(SELECT TOP(1) x.Version,x.StepsJson FROM dbo.LessonVersions x WHERE x.LessonId=l.Id ORDER BY x.Version DESC) v
CROSS APPLY OPENJSON(v.StepsJson) s;
';
EXEC [LingWay].sys.sp_executesql N'
CREATE OR ALTER VIEW dbo.vwLearningResults AS
SELECT a.Id,u.LegacyDisplayName AS StudentName,u.Email,l.Title AS Lesson,
       m.Title AS Module,a.LessonVersion,a.Score,a.Stars,a.IsPassed,
       a.DurationSeconds,a.CompletedAt
FROM dbo.Attempts a JOIN dbo.AspNetUsers u ON u.Id=a.UserId
JOIN dbo.Lessons l ON l.Id=a.LessonId JOIN dbo.Modules m ON m.Id=l.ModuleId;
';
